1	export type Item = {
2	  type: string;
3	  material?: string;
4	  enchantment?: number;
5	  cursed?: boolean;
6	};
7	
8	export type Step = {
9	  op: string;
10	  items?: Item[];
11	};
12	
13	export type Customer = {
14	  yearsWithMHPCO: number;
15	};
16	
17	export type Scenario = {
18	  customer: Customer;
19	  steps: Step[];
20	};
21	
22	export type QuoteResult = {
23	  premium: number;
24	};
25	
26	export type ScenarioResults = {
27	  results: QuoteResult[];
28	};
29	
30	const PROCESSING_FEE = 5;
31	
32	const BASE_PREMIUM_BY_TYPE: Record<string, number> = {
33	  sword: 100,
34	  amulet: 60,
35	  staff: 80,
36	  potion: 40,
37	  rune: 25,
38	  moonstone: 25,
39	};
40	
41	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
42	
43	const percentOf = (amount: number, percent: number): number =>
44	  (amount * percent) / 100;
45	
46	const itemBasePremium = (item: Item): number =>
47	  BASE_PREMIUM_BY_TYPE[item.type];
48	
49	const BLOCK_SIZE = 3;
50	
51	const BLOCK_PREMIUM = 60;
52	
53	const sumOf = (amounts: number[]): number =>
54	  amounts.reduce((sum, amount) => sum + amount, 0);
55	
56	const formsABlock = (items: Item[]): boolean => items.length === BLOCK_SIZE;
57	
58	const sumOfItemBasePremiums = (items: Item[]): number =>
59	  sumOf(items.map(itemBasePremium));
60	
61	const groupByType = (items: Item[]): Item[][] => {
62	  const types = new Set(items.map((item) => item.type));
63	
64	  return [...types].map((type) => items.filter((item) => item.type === type));
65	};
66	
67	const alikeGroupBasePremium = (items: Item[]): number =>
68	  formsABlock(items) ? BLOCK_PREMIUM : sumOfItemBasePremiums(items);
69	
70	const policyBasePremium = (items: Item[]): number =>
71	  sumOf(groupByType(items).map(alikeGroupBasePremium));
72	
73	const roundPremiumInMHPCOsFavor = (amount: number): number =>
74	  Math.ceil(amount);
75	
76	// The inputs a single quote is computed from. Today only `items` is consumed;
77	// `customer` is threaded through so policy-wide modifiers that depend on
78	// customer history (loyalty, follow-up contract) have a seat at the table.
79	type QuoteRequest = {
80	  customer: Customer;
81	  items: Item[];
82	};
83	
84	const LOYALTY_YEARS = 2;
85	
86	const LOYALTY_DISCOUNT_PERCENT = -20;
87	
88	const isLoyal = (customer: Customer): boolean =>
89	  customer.yearsWithMHPCO >= LOYALTY_YEARS;
90	
91	// Policy-wide modifiers do NOT compound: each is an independent percentage of
92	// the policy base premium, and they are summed. Chaining them (base * 1.1 * 0.8)
93	// would give a different, wrong answer.
94	const policyModifierPercents = (request: QuoteRequest): number[] => [
95	  FIRST_INSURANCE_SURCHARGE_PERCENT,
96	  ...(isLoyal(request.customer) ? [LOYALTY_DISCOUNT_PERCENT] : []),
97	];
98	
99	const applyPolicyModifiers = (
100	  basePremium: number,
101	  request: QuoteRequest,
102	): number =>
103	  basePremium +
104	  sumOf(
105	    policyModifierPercents(request).map((percent) =>
106	      percentOf(basePremium, percent),
107	    ),
108	  );
109	
110	const CURSE_SURCHARGE_PERCENT = 50;
111	
112	const HIGH_ENCHANTMENT_LEVEL = 5;
113	
114	const HIGH_ENCHANTMENT_SURCHARGE_PERCENT = 30;
115	
116	const isHighlyEnchanted = (item: Item): boolean =>
117	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL;
118	
119	const isCursed = (item: Item): boolean => item.cursed === true;
120	
121	type ItemSurchargeRule = {
122	  applies: (item: Item) => boolean;
123	  percent: number;
124	};
125	
126	const ITEM_SURCHARGE_RULES: ItemSurchargeRule[] = [
127	  { applies: isCursed, percent: CURSE_SURCHARGE_PERCENT },
128	  { applies: isHighlyEnchanted, percent: HIGH_ENCHANTMENT_SURCHARGE_PERCENT },
129	];
130	
131	// Item-scoped surcharges are charged on the item's own base premium, so they
132	// must NOT go through applyPolicyModifiers.
133	const itemSurcharges = (item: Item): number =>
134	  sumOf(
135	    ITEM_SURCHARGE_RULES.filter((rule) => rule.applies(item)).map((rule) =>
136	      percentOf(itemBasePremium(item), rule.percent),
137	    ),
138	  );
139	
140	const policyItemSurcharges = (items: Item[]): number =>
141	  sumOf(items.map(itemSurcharges));
142	
143	const quotePremium = (request: QuoteRequest): number =>
144	  roundPremiumInMHPCOsFavor(
145	    applyPolicyModifiers(policyBasePremium(request.items), request) +
146	      policyItemSurcharges(request.items) +
147	      PROCESSING_FEE,
148	  );
149	
150	export const runScenario = (scenario: Scenario): ScenarioResults => ({
151	  results: scenario.steps.map((step) => ({
152	    premium: quotePremium({
153	      customer: scenario.customer,
154	      items: step.items ?? [],
155	    }),
156	  })),
157	});
